<?php
require_once __DIR__ . '/rector_common.php';
$asignaciones = $pdo->query("SELECT u.nombre AS docente, m.nombre AS materia, c.nombre AS curso, s.nombre AS salon, h.dia, h.hora_inicio, h.hora_fin, p.nombre AS periodo FROM asignacion_academica aa JOIN usuario u ON aa.id_docente=u.id_usuario JOIN materia m ON aa.id_materia=m.id_materia JOIN curso c ON aa.id_curso=c.id_curso JOIN salon s ON aa.id_salon=s.id_salon JOIN horario h ON aa.id_horario=h.id_horario JOIN periodo_academico p ON aa.id_periodo=p.id_periodo ORDER BY aa.id_asignacion DESC LIMIT 20")->fetchAll();
rector_layout_start('Asignaciones Académicas', 'asignaciones');
?><div class="section-title"><i class="fa-solid fa-calendar-days"></i> Asignaciones Académicas</div><div class="card"><div class="table-wrap"><?php if (!$asignaciones): ?><div class="empty-state"><i class="fa-solid fa-calendar-xmark"></i><p>No hay asignaciones registradas aún</p></div><?php else: ?><table><thead><tr><th>Docente</th><th>Materia</th><th>Curso</th><th>Salón</th><th>Día</th><th>Hora</th><th>Periodo</th></tr></thead><tbody><?php foreach ($asignaciones as $a): ?><tr><td><?= htmlspecialchars($a['docente']) ?></td><td><?= htmlspecialchars($a['materia']) ?></td><td><span class="badge blue"><?= htmlspecialchars($a['curso']) ?></span></td><td><?= htmlspecialchars($a['salon']) ?></td><td><?= htmlspecialchars($a['dia']) ?></td><td><?= substr($a['hora_inicio'], 0, 5) ?> - <?= substr($a['hora_fin'], 0, 5) ?></td><td><?= htmlspecialchars($a['periodo']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></div><?php rector_layout_end(); ?>
